package com.tekwatt.audit.controller;import com.tekwatt.audit.dto.*;import com.tekwatt.audit.service.AuditService;import jakarta.validation.Valid;import java.time.Instant;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/audit-events")public class AuditController{private final AuditService service;public AuditController(AuditService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)AuditEventResponse create(@Valid@RequestBody CreateAuditEventRequest r){return service.create(r);}@GetMapping("/{id}")AuditEventResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping Page<AuditEventResponse>search(@RequestParam UUID tenantId,@RequestParam(required=false)String action,@RequestParam(required=false)String resourceType,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to,Pageable pageable){return service.search(tenantId,action,resourceType,from,to,pageable);}}
